import json
import re

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class MiraStatusJSONValidator(Component):
    display_name = "Mira Status JSON Validator"
    description = "Validates grounded task status responses."
    icon = "shield-check"
    name = "MiraStatusJSONValidator"

    inputs = [
        MessageTextInput(
            name="model_response",
            display_name="Model Response",
            required=True,
        ),
        MessageTextInput(
            name="task_context",
            display_name="Task Context",
            required=True,
        ),
        MessageTextInput(
            name="user_request",
            display_name="User Request",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="validated_response",
            display_name="Validated Response",
            method="validate_json",
        )
    ]

    PROJECT = "AI Adoption Project at ABCDE Ltd."
    STATUSES = ("Done", "In Progress", "Blocked", "To Do")
    TASK_FIELDS = (
        "task_id", "task_name", "status",
        "assignee", "priority", "sprint", "due_date",
    )
    REQUIRED = (
        "status", "report_type", "project_name",
        "report_scope", "executive_summary",
        "task_counts", "tasks", "blockers",
        "overdue_task_ids", "recommendations",
        "data_quality_notes", "missing_information",
        "sources_used",
    )
    ARRAYS = (
        "tasks", "blockers", "overdue_task_ids",
        "recommendations", "data_quality_notes",
        "missing_information", "sources_used",
    )

    def _text(self, value):
        return str(getattr(value, "text", value) or "")

    def _parse(self, value):
        raw = self._text(value).strip()
        raw = re.sub(
            r"^```(?:json)?\s*", "",
            raw,
            flags=re.IGNORECASE,
        )
        raw = re.sub(r"\s*```$", "", raw)
        return json.loads(raw)

    def _intent(self, question):
        q = question.lower()

        if re.search(r"\be-?mail\b", q):
            return "email"

        # Counts-only intent takes precedence over status keywords.
        # E.g. "How many tasks are Done, In Progress, Blocked, and To Do?"
        if re.search(
            r"\b(counts?|how many|number of tasks)\b", q
        ) and not re.search(
            r"\b(list|show|details|each task|task list|which tasks)\b", q
        ):
            return "counts"

        # Focused blocked-task listing, not a count or general report.
        if re.search(r"\b(blocked|blockers|blocking)\b", q) and re.search(
            r"\b(which|list|show|identify|blocked tasks|blockers)\b", q
        ) and not re.search(r"\b(report|weekly|e-?mail)\b", q):
            return "blocked_tasks"

        if re.search(
            r"\bT\d{3}\b", question, re.IGNORECASE
        ) and re.search(
            r"\b(status of|task status)\b", q
        ):
            return "task_inquiry"

        if "weekly" in q and "report" in q:
            return "weekly_report"

        return "general_report"

    def _check_summary(
        self, summary, context, intent, errors
    ):
        text = summary.lower()

        # An undated source cannot be called the
        # latest verified snapshot.
        if context.get("snapshot_date") == "NOT_PROVIDED":
            if re.search(
                r"\b(latest|current|most recent)\s+"
                r"(snapshot|update|review)\b",
                text,
            ):
                errors.append(
                    "Summary implies a recent snapshot "
                    "without a source timestamp"
                )

        # Task statuses alone cannot establish
        # schedule health.
        if re.search(
            r"\b(on track|ahead of schedule|"
            r"behind schedule|project is healthy|"
            r"significant strides)\b",
            text,
        ):
            errors.append(
                "Unsupported project progress assessment"
            )

        if context.get("scope_type") not in (
            "sprint", "task"
        ):
            return

        # Detect the specific scope-mixing failure
        # previously observed in T5 and T12.
        source_total = context.get(
            "total_source_tasks"
        )
        selected_total = context.get(
            "selected_task_count"
        )

        if (
            isinstance(source_total, int)
            and source_total != selected_total
            and re.search(
                rf"\b{source_total}\s+tasks?\b",
                text,
            )
        ):
            errors.append(
                "Scoped summary contains "
                "whole-project task total"
            )

        # Reject known whole-project count phrases
        # when they conflict with selected counts.
        selected_counts = context.get(
            "selected_counts", {}
        )

        project_counts = {
            "completed": 5,
            "in progress": 3,
            "blocked": 1,
            "to do": 16,
        }

        selected_lookup = {
            "completed": selected_counts.get("Done", 0),
            "in progress": selected_counts.get(
                "In Progress", 0
            ),
            "blocked": selected_counts.get(
                "Blocked", 0
            ),
            "to do": selected_counts.get("To Do", 0),
        }

        # Only reject when the narrative uses a
        # conflicting whole-project value.
        for label, number in project_counts.items():
            if number == selected_lookup[label]:
                continue

            if re.search(
                rf"\b{number}\s+(?:tasks?\s+)?"
                rf"(?:are\s+|were\s+|still\s+)?"
                rf"{re.escape(label)}\b",
                text,
            ):
                errors.append(
                    "Possible project-wide count in "
                    "scoped summary: " + label
                )

        # A scoped report should not bring in the
        # unrelated narrative-vs-CSV discrepancy.
        if re.search(
            r"\b(narrative|discrepancy)\b",
            text,
        ):
            errors.append(
                "Scoped summary includes unrelated "
                "whole-project data-quality discussion"
            )

    def validate_json(self) -> Message:
        errors = []
        data = {}

        try:
            data = self._parse(self.model_response)
            context = self._parse(self.task_context)
            question = self._text(self.user_request)

            if not isinstance(data, dict):
                raise ValueError(
                    "Model response must be a JSON object"
                )

            if not isinstance(context, dict):
                raise ValueError(
                    "Task context must be a JSON object"
                )

            for field in self.REQUIRED:
                if field not in data:
                    errors.append(
                        "Missing field: " + field
                    )

            for field in self.ARRAYS:
                if not isinstance(data.get(field), list):
                    errors.append(
                        field + " must be an array"
                    )

            if not isinstance(
                data.get("task_counts"), dict
            ):
                errors.append(
                    "task_counts must be an object"
                )

            if data.get("status") not in (
                "SUCCESS",
                "INSUFFICIENT_INFORMATION",
            ):
                errors.append("Invalid status")

            def array(name):
                value = data.get(name)
                return value if isinstance(
                    value, list
                ) else []

            tasks = array("tasks")
            blockers = array("blockers")
            overdue = array("overdue_task_ids")
            sources = array("sources_used")
            missing = array("missing_information")
            counts = data.get("task_counts")
            if not isinstance(counts, dict):
                counts = {}

            intent = self._intent(question)
            source_status = context.get("data_status")

            # An insufficiently specified request must not be converted
            # into a successful report merely because a CSV is available.
            # This rule is intentionally narrow: it applies to the official
            # vague weekly-report case and similarly empty reporting briefs.
            vague_request = bool(re.search(
                r"\bthings are going fine\b", question, re.IGNORECASE
            )) and not bool(re.search(
                r"\b(sprint\s*\d+|T\d{3}|ABCDE|task board)\b",
                question, re.IGNORECASE
            ))

            if vague_request:
                if data.get("status") != "INSUFFICIENT_INFORMATION":
                    errors.append(
                        "Vague request requires INSUFFICIENT_INFORMATION"
                    )
                if data.get("report_type") != "Weekly Status Report":
                    errors.append("Incorrect weekly report type")
                if data.get("report_scope") != "Unspecified":
                    errors.append("Vague request requires unspecified scope")
                if data.get("project_name") != self.PROJECT:
                    errors.append("Incorrect project name")
                if tasks or blockers or overdue:
                    errors.append(
                        "Vague request must not include task-related records"
                    )
                if any(counts.get(key) != 0 for key in self.STATUSES):
                    errors.append(
                        "Vague request requires zero placeholder counts"
                    )
                if sources:
                    errors.append(
                        "Vague request must not claim a source was used"
                    )
                if not missing:
                    errors.append(
                        "Vague request must identify missing information"
                    )
                if not str(data.get("executive_summary") or "").strip():
                    errors.append("Vague request requires an explanation")

            elif source_status != "AVAILABLE":
                if data.get("status") != (
                    "INSUFFICIENT_INFORMATION"
                ):
                    errors.append(
                        "Missing or invalid source requires "
                        "INSUFFICIENT_INFORMATION"
                    )

                if tasks or blockers or overdue:
                    errors.append(
                        "Unavailable source requires "
                        "empty task-related arrays"
                    )

                if not missing:
                    errors.append(
                        "Explain unavailable source "
                        "in missing_information"
                    )

                if any(
                    counts.get(key) not in (0, None)
                    for key in self.STATUSES
                ):
                    errors.append(
                        "Unavailable source cannot claim "
                        "verified nonzero task counts"
                    )

            else:
                if data.get("status") != "SUCCESS":
                    errors.append(
                        "Available source requires SUCCESS"
                    )

                if data.get("project_name") != self.PROJECT:
                    errors.append(
                        "Incorrect project name"
                    )

                selected = context.get(
                    "selected_tasks", []
                )

                if not isinstance(selected, list):
                    raise ValueError(
                        "Invalid selected_tasks context"
                    )

                source_by_id = {
                    item["task_id"]: item
                    for item in selected
                    if isinstance(item, dict)
                    and isinstance(
                        item.get("task_id"), str
                    )
                }

                expected_counts = context.get(
                    "selected_counts", {}
                )

                if not isinstance(
                    expected_counts, dict
                ):
                    raise ValueError(
                        "Invalid selected_counts context"
                    )

                for key in self.STATUSES:
                    if counts.get(key) != (
                        expected_counts.get(key, 0)
                    ):
                        errors.append(
                            "Count mismatch for " + key
                        )

                reported_ids = []

                for task in tasks:
                    if not isinstance(task, dict):
                        errors.append(
                            "Task must be an object"
                        )
                        continue

                    task_id = task.get("task_id")

                    if not isinstance(task_id, str):
                        errors.append(
                            "Task ID must be a string"
                        )
                        continue

                    reported_ids.append(task_id)
                    original = source_by_id.get(task_id)

                    if original is None:
                        errors.append(
                            "Out-of-scope task: " + task_id
                        )
                        continue

                    for field in self.TASK_FIELDS:
                        if task.get(field) != (
                            original.get(field)
                        ):
                            errors.append(
                                task_id + ": mismatch in "
                                + field
                            )

                if len(reported_ids) != len(
                    set(reported_ids)
                ):
                    errors.append(
                        "Duplicate task IDs"
                    )

                if intent == "counts":
                    if tasks:
                        errors.append(
                            "Counts-only request requires "
                            "tasks=[]"
                        )
                elif intent == "blocked_tasks":
                    expected_blocked_ids = {
                        task_id for task_id, item in source_by_id.items()
                        if item.get("status") == "Blocked"
                    }
                    if set(reported_ids) != expected_blocked_ids:
                        errors.append(
                            "Blocked-task task coverage mismatch"
                        )
                elif set(reported_ids) != set(
                    source_by_id
                ):
                    errors.append(
                        "Task coverage mismatch"
                    )

                expected_blockers = {
                    item["task_id"]
                    for item in selected
                    if isinstance(item, dict)
                    and item.get("status") == "Blocked"
                    and isinstance(
                        item.get("task_id"), str
                    )
                }

                blocker_ids = []

                for blocker in blockers:
                    if not isinstance(blocker, dict):
                        errors.append(
                            "Blocker must be an object"
                        )
                        continue

                    task_id = blocker.get("task_id")
                    if not isinstance(task_id, str):
                        errors.append(
                            "Blocker must have a task_id"
                        )
                    else:
                        blocker_ids.append(task_id)

                if len(blocker_ids) != len(
                    set(blocker_ids)
                ):
                    errors.append(
                        "Duplicate blocker IDs"
                    )

                if intent == "counts":
                    if blockers:
                        errors.append(
                            "Counts-only request requires "
                            "blockers=[]"
                        )
                elif set(blocker_ids) != (
                    expected_blockers
                ):
                    errors.append(
                        "Blocked-task coverage mismatch"
                    )

                expected_overdue = (
                    context.get("overdue_task_ids")
                    or []
                )

                if intent == "counts":
                    if overdue:
                        errors.append(
                            "Counts-only request requires "
                            "overdue_task_ids=[]"
                        )
                elif (
                    not all(
                        isinstance(x, str)
                        for x in overdue
                    )
                    or len(overdue) != len(
                        set(overdue)
                    )
                    or set(overdue) != set(
                        expected_overdue
                    )
                ):
                    errors.append(
                        "Overdue task IDs mismatch"
                    )

                if context.get(
                    "source_file"
                ) not in sources:
                    errors.append(
                        "Source file missing from "
                        "sources_used"
                    )

                summary = str(
                    data.get("executive_summary")
                    or ""
                ).strip()

                report_type = data.get(
                    "report_type"
                )

                if intent == "email":
                    if report_type != (
                        "Stakeholder Update Email"
                    ):
                        errors.append(
                            "Incorrect email report type"
                        )

                    if not summary.startswith(
                        "Dear Stakeholders,"
                    ):
                        errors.append(
                            "Email missing greeting"
                        )

                    if "Best regards," not in summary:
                        errors.append(
                            "Email missing sign-off"
                        )

                elif intent == "counts":
                    if report_type != (
                        "Task Status Counts"
                    ):
                        errors.append(
                            "Incorrect counts report type"
                        )

                elif intent == "task_inquiry":
                    if report_type != (
                        "Task Status Inquiry"
                    ):
                        errors.append(
                            "Incorrect task inquiry type"
                        )

                elif intent == "weekly_report":
                    if report_type != (
                        "Weekly Status Report"
                    ):
                        errors.append(
                            "Incorrect weekly report type"
                        )

                    if re.search(
                        r"Dear Stakeholders|"
                        r"Best regards|\[Your Name\]",
                        summary,
                        re.IGNORECASE,
                    ):
                        errors.append(
                            "Weekly report uses "
                            "email formatting"
                        )

                elif intent in ("general_report", "blocked_tasks"):
                    if report_type != "Project Status Report":
                        errors.append(
                            "Incorrect general report type"
                        )

                self._check_summary(
                    summary, context, intent, errors
                )

            result = {
                "validation_status": (
                    "PASS" if not errors else "FAIL"
                ),
                "validation_errors": errors,
                "validated_data": data,
            }

        except Exception as exc:
            result = {
                "validation_status": "FAIL",
                "validation_errors": [
                    "Validator error: " + str(exc)
                ],
                "validated_data": data,
            }

        self.status = result["validation_status"]

        return Message(
            text=json.dumps(
                result,
                indent=2,
                ensure_ascii=False,
            )
        )

import csv
import json
import re
from collections import Counter
from datetime import date
from pathlib import Path

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class MiraStatusTaskProcessor(Component):
    display_name = "Mira Status Task Processor"
    description = "Reads, validates and scopes project task data."
    icon = "file-spreadsheet"
    name = "MiraStatusTaskProcessor"

    inputs = [
        MessageTextInput(
            name="csv_path",
            display_name="CSV File Path",
            required=True,
        ),
        MessageTextInput(
            name="user_request",
            display_name="User Request",
            required=True,
        ),
        MessageTextInput(
            name="as_of_date",
            display_name="As-of Date (YYYY-MM-DD, optional)",
            required=False,
        ),
    ]

    outputs = [
        Output(
            name="task_context",
            display_name="Task Context",
            method="process_tasks",
        )
    ]

    COLUMNS = (
        "task_id", "task_name", "status", "assignee",
        "priority", "sprint", "due_date",
        "labels", "description",
    )

    STATUSES = ("Done", "In Progress", "Blocked", "To Do")

    def _text(self, value):
        return str(getattr(value, "text", value) or "").strip()

    def _counts(self, tasks):
        counted = Counter(
            task["status"] for task in tasks
        )
        return {
            status: counted.get(status, 0)
            for status in self.STATUSES
        }

    def _message(self, data):
        return Message(
            text=json.dumps(
                data,
                indent=2,
                ensure_ascii=False,
            )
        )

    def process_tasks(self) -> Message:
        path_text = self._text(self.csv_path)
        request = self._text(self.user_request)
        date_text = self._text(self.as_of_date)

        path = Path(path_text) if path_text else None

        if path is None or not path.is_file():
            return self._message({
                "data_status": "SOURCE_UNAVAILABLE",
                "error": "Task board CSV not found at configured path",
                "selected_tasks": [],
                "selected_counts": self._counts([]),
                "tasks": [],
            })

        try:
            as_of = (
                date.fromisoformat(date_text)
                if date_text
                else None
            )

            with path.open(
                "r", encoding="utf-8-sig", newline=""
            ) as file:
                reader = csv.DictReader(file)

                if not reader.fieldnames:
                    raise ValueError("CSV has no headers")

                missing_columns = (
                    set(self.COLUMNS)
                    - set(reader.fieldnames)
                )

                if missing_columns:
                    raise ValueError(
                        "Missing CSV columns: "
                        + ", ".join(sorted(missing_columns))
                    )

                tasks = []
                seen_ids = set()

                for row in reader:
                    task = {
                        key: str(row.get(key) or "").strip()
                        for key in self.COLUMNS
                    }

                    task_id = task["task_id"]

                    if not task_id:
                        raise ValueError("Blank task ID")

                    if task_id in seen_ids:
                        raise ValueError(
                            "Duplicate task ID: " + task_id
                        )

                    seen_ids.add(task_id)

                    if task["status"] not in self.STATUSES:
                        raise ValueError(
                            "Invalid status for " + task_id
                        )

                    if task["due_date"]:
                        date.fromisoformat(task["due_date"])

                    tasks.append(task)

            # Determine which tasks the user requested.
            sprint_match = re.search(
                r"\bsprint\s*(\d+)\b",
                request,
                re.IGNORECASE,
            )

            requested_sprint = (
                "Sprint " + sprint_match.group(1)
                if sprint_match
                else None
            )

            requested_ids = sorted(set(
                match.upper()
                for match in re.findall(
                    r"\bT\d{3}\b",
                    request,
                    re.IGNORECASE,
                )
            ))

            if requested_ids:
                selected = [
                    task for task in tasks
                    if task["task_id"].upper()
                    in requested_ids
                ]
                scope = "task"

            elif requested_sprint:
                selected = [
                    task for task in tasks
                    if task["sprint"].lower()
                    == requested_sprint.lower()
                ]
                scope = "sprint"

            else:
                selected = list(tasks)
                scope = "project"

            selected_counts = self._counts(selected)

            # Only compute overdue when a reference
            # date was explicitly supplied.
            overdue_ids = None

            if as_of:
                overdue_ids = [
                    task["task_id"]
                    for task in selected
                    if task["status"] != "Done"
                    and task["due_date"]
                    and date.fromisoformat(
                        task["due_date"]
                    ) < as_of
                ]

            notes = [
                "Source CSV has no snapshot timestamp.",
                "Task statuses are historical source "
                "values, not verified live statuses.",
                "Assignment narrative reports 3 Done; "
                "source CSV records 5 Done.",
            ]

            result = {
                "data_status": "AVAILABLE",
                "source_file": path.name,
                "source_type": "uploaded_task_board_csv",
                "snapshot_date": "NOT_PROVIDED",
                "report_as_of_date": (
                    as_of.isoformat() if as_of else None
                ),
                "scope_type": scope,
                "requested_sprint": requested_sprint,
                "requested_task_ids": requested_ids,
                "total_source_tasks": len(tasks),
                "selected_task_count": len(selected),
                "selected_counts": selected_counts,
                "selected_tasks": selected,
                "overdue_task_ids": overdue_ids,
                "data_quality_notes": notes,
            }

            # Whole-project counts are only supplied
            # when the user requests project scope.
            if scope == "project":
                result["overall_counts"] = (
                    self._counts(tasks)
                )

            # Avoid falsely reporting missing sprint
            # or task IDs as a successful empty report.
            if not selected:
                result["data_status"] = (
                    "REQUESTED_SCOPE_NOT_FOUND"
                )
                result["error"] = (
                    "No tasks match the requested scope"
                )

            return self._message(result)

        except Exception as exc:
            return self._message({
                "data_status": "INVALID_SOURCE",
                "error": str(exc),
                "selected_tasks": [],
                "selected_counts": self._counts([]),
                "tasks": [],
            })
